float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

vec3 color(float t){
    vec3 a = vec3(0.368, 0.746, 0.903);
    vec3 b = vec3(0.728, 0.418, 0.598);
    vec3 c = vec3(1.218, 0.548, 0.638);
    vec3 d = vec3(2.458, 1.748, 1.218);
    return a + b*cos( 6.283185*(c*t+d) );
}

float Rect(float len, float high, float blur, vec2 uv){
    float l = len / 2.0;
    float h = high / 2.0;

    float lenB = smoothstep(l + blur,l - blur, uv.x) * smoothstep(- l - blur,- l + blur, uv.x);
    float highB = smoothstep(h + blur,h - blur, uv.y) * smoothstep(- h - blur,- h + blur, uv.y); 

    return lenB * highB;
}

vec3 SineWave(float num, vec2 uv){
    float speed = 3.0 + rand(vec2(num)) * 5.0;
    float freq = 3.0 + rand(vec2(num) * ceil(iTime / speed)) * 5.0;
    float amp = 0.1 + rand(vec2(num) * ceil(iTime / speed) + 1.0) * 0.1;
    float hight = -0.6 + rand(vec2(num) * ceil(iTime / speed) + 2.0) * 1.3;
    float len = 1.0 + rand(vec2(num) * ceil(iTime / speed) + 3.0) * 1.0;
    float blur = 0.001 +  rand(vec2(num) * ceil(iTime / speed) + 4.0) * 0.025;

    float f = (-1.0 * iResolution.x / iResolution.y - len / 2.0) + fract(iTime / speed) * (2.0 * iResolution.x / iResolution.y + len);

    float sineValue = sin(freq*uv.x + iTime * 1.5) * amp;

    uv.y += sineValue + hight;
    uv.x += -f;

    float line = Rect(len, 0.025, blur, uv);

    return line * color(f);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 sum = vec3(0.0);

    float count = 50.0;
    for(float i = 0.0; i < count; ++i){
        sum += SineWave(i, uv);
    }

    vec3 col =  sum;
    // Output to screen
    fragColor = vec4(col, 1.0);
}
